pub fn longest_valid_parentheses(s: &str) -> usize {
    let mut stack: Vec<isize> = vec![-1];
    let mut max_len: usize = 0;
    for (i, ch) in s.chars().enumerate() {
        if ch == '(' {
            stack.push(i as isize);
        } else {
            stack.pop();
            if let Some(&last_idx) = stack.last() {
                max_len = max_len.max((i as isize - last_idx) as usize);
            } else {
                stack.push(i as isize);
            }
        }
    }
    max_len
}
fn main() {
    let test1 = longest_valid_parentheses("(()");
    let test2 = longest_valid_parentheses(")()())");
    println!("Length of longest valid parentheses in '(()': {}", test1);
    println!("Length of longest valid parentheses in ')()())': {}", test2);
}
